/**
 * Anthropic Stream Processor - Convert Anthropic streaming responses to AGUI events
 */

import Anthropic from '@anthropic-ai/sdk';
import { EventType } from '@ag-ui/client';

export interface StreamContext {
  threadId: string;
  runId: string;
  messageId: string;
}

export interface StreamState {
  hasStarted: boolean;
  fullContent: string;
  toolCallsMap: Map<string, { name: string; input: string }>;
  indexToIdMap: Map<number, string>;
}

/**
 * Process Anthropic streaming events and emit AGUI events
 */
export async function* processAnthropicStream(
  stream: AsyncIterable<Anthropic.MessageStreamEvent>,
  context: StreamContext
) {
  const { threadId, runId, messageId } = context;
  const state: StreamState = {
    hasStarted: false,
    fullContent: '',
    toolCallsMap: new Map(),
    indexToIdMap: new Map()
  };

  for await (const event of stream) {
    if (event.type === 'content_block_start') {
      const block = event.content_block;
      
      if (block.type === 'text') {
        if (!state.hasStarted) {
          yield {
            type: EventType.TEXT_MESSAGE_START,
            threadId,
            runId,
            messageId,
            role: 'assistant'
          };
          state.hasStarted = true;
        }
      } else if (block.type === 'tool_use') {
        // Store the mapping between index and tool call ID
        state.indexToIdMap.set(event.index, block.id);
        
        yield {
          type: EventType.TOOL_CALL_START,
          threadId,
          runId,
          toolCallId: block.id,
          toolCallName: block.name
        };
        
        state.toolCallsMap.set(block.id, {
          name: block.name,
          input: ''
        });
      }
    } else if (event.type === 'content_block_delta') {
      const delta = event.delta;
      
      if (delta.type === 'text_delta') {
        state.fullContent += delta.text;
        yield {
          type: EventType.TEXT_MESSAGE_CONTENT,
          threadId,
          runId,
          messageId,
          delta: delta.text
        };
      } else if (delta.type === 'input_json_delta') {
        // Get the tool call ID from the index
        const toolCallId = state.indexToIdMap.get(event.index);
        if (toolCallId) {
          const toolCall = state.toolCallsMap.get(toolCallId);
          if (toolCall) {
            toolCall.input += delta.partial_json;
            
            yield {
              type: EventType.TOOL_CALL_ARGS,
              threadId,
              runId,
              toolCallId,
              delta: delta.partial_json
            };
          }
        }
      }
    } else if (event.type === 'content_block_stop') {
      // Check if this was a tool call
      const toolCallId = state.indexToIdMap.get(event.index);
      if (toolCallId && state.toolCallsMap.has(toolCallId)) {
        yield {
          type: EventType.TOOL_CALL_END,
          threadId,
          runId,
          toolCallId
        };
      }
    }
  }

  // Emit TEXT_MESSAGE_END if we had text content
  if (state.hasStarted) {
    yield {
      type: EventType.TEXT_MESSAGE_END,
      threadId,
      runId,
      messageId
    };
  }

  // Emit RUN_FINISHED
  yield {
    type: EventType.RUN_FINISHED,
    threadId,
    runId
  };
}

