/**
 * OpenAI Converter - AGUI Protocol to OpenAI Format
 */

import OpenAI from "openai";
import { Message, Tool } from "@ag-ui/client";

/**
 * Convert AGUI messages to OpenAI chat completion format
 */
export function convertMessagesToOpenAI(
  messages: Message[],
  systemPrompt?: string
): OpenAI.Chat.ChatCompletionMessageParam[] {
  const openaiMessages: OpenAI.Chat.ChatCompletionMessageParam[] = [];

  // Add system prompt if provided
  if (systemPrompt) {
    openaiMessages.push({
      role: "system",
      content: systemPrompt,
    });
  }

  // Convert messages
  for (const msg of messages) {
    if (msg.role === "user") {
      openaiMessages.push({
        role: "user",
        content:
          typeof msg.content === "string"
            ? msg.content
            : JSON.stringify(msg.content),
      });
    } else if (msg.role === "assistant") {
      openaiMessages.push({
        role: "assistant",
        content:
          typeof msg.content === "string"
            ? msg.content
            : JSON.stringify(msg.content) || "",
        tool_calls: msg.toolCalls?.map((tc: any) => ({
          id: tc.id,
          type: "function" as const,
          function: {
            name: tc.function.name,
            arguments: tc.function.arguments,
          },
        })),
      });
    } else if (msg.role === "tool") {
      openaiMessages.push({
        role: "tool",
        tool_call_id: msg.toolCallId!,
        content:
          typeof msg.content === "string"
            ? msg.content
            : JSON.stringify(msg.content),
      });
    }
  }

  return openaiMessages;
}

/**
 * Convert AGUI tools to OpenAI function calling format
 */
export function convertToolsToOpenAI(
  tools?: Tool[]
): OpenAI.Chat.ChatCompletionTool[] | undefined {
  if (!tools || tools.length === 0) {
    return undefined;
  }

  return tools.map((tool: any) => ({
    type: "function" as const,
    function: {
      name: tool.name,
      description: tool.description,
      parameters:
        typeof tool.parameters === "string"
          ? JSON.parse(tool.parameters)
          : tool.parameters,
    },
  }));
}

/**
 * Create OpenAI streaming request options
 */
export function createOpenAIStreamOptions(config: {
  modelName: string;
  messages: OpenAI.Chat.ChatCompletionMessageParam[];
  tools?: OpenAI.Chat.ChatCompletionTool[];
  temperature?: number;
  maxTokens?: number;
  user?: string;
}): OpenAI.Chat.ChatCompletionCreateParamsStreaming {
  return {
    model: config.modelName,
    messages: config.messages,
    tools: config.tools,
    temperature: config.temperature,
    max_tokens: config.maxTokens,
    user: config.user,
    stream: true,
  };
}
