/**
 * OpenAI Stream Processor - Convert OpenAI streaming responses to AGUI events
 */

import OpenAI from "openai";
import { EventType } from "@ag-ui/client";

export interface StreamContext {
  threadId: string;
  runId: string;
  messageId: string;
}

export interface StreamState {
  hasStarted: boolean;
  fullContent: string;
  toolCallsMap: Map<string, { name: string; args: string }>;
}

export type Delta =
  OpenAI.Chat.Completions.ChatCompletionChunk["choices"][number]["delta"] & {
    reasoning_content?: string;
  };

/**
 * Process OpenAI streaming chunk and emit AGUI events
 */
export async function* processOpenAIStream(
  stream: AsyncIterable<OpenAI.Chat.Completions.ChatCompletionChunk>,
  context: StreamContext
) {
  const { threadId, runId, messageId } = context;
  const state: StreamState = {
    hasStarted: false,
    fullContent: "",
    toolCallsMap: new Map(),
  };
  const reasoningState: StreamState = {
    hasStarted: false,
    fullContent: "",
    toolCallsMap: new Map(),
  };

  for await (const chunk of stream) {
    const delta = chunk.choices[0]?.delta as Delta;
    if (!delta) continue;

    if (delta.role === "tool") {
      const toolCallId = (delta as any).tool_call_id;
      if (toolCallId) {
        if (state.toolCallsMap.has(toolCallId)) {
          yield {
            type: EventType.TOOL_CALL_END,
            threadId,
            runId,
            toolCallId,
          };
          state.toolCallsMap.delete(toolCallId);
        }
        yield {
          type: EventType.TOOL_CALL_RESULT,
          threadId,
          runId,
          toolCallId,
          content: delta.content || "",
        };
      }
      continue;
    }

    // Handle text content
    if (delta.content) {
      // End reasoning message if it was started
      if (reasoningState.hasStarted) {
        reasoningState.hasStarted = false;
        yield {
          type: EventType.THINKING_TEXT_MESSAGE_END,
          threadId,
          runId,
          messageId,
        };
        yield {
          type: EventType.THINKING_END,
          threadId,
          runId,
          messageId,
        };
      }

      if (!state.hasStarted) {
        yield {
          type: EventType.TEXT_MESSAGE_START,
          threadId,
          runId,
          messageId,
          role: "assistant",
        };
        state.hasStarted = true;
      }

      state.fullContent += delta.content;
      yield {
        type: EventType.TEXT_MESSAGE_CONTENT,
        threadId,
        runId,
        messageId,
        delta: delta.content,
      };
    }

    // Handle reasoning content
    if (delta.reasoning_content) {
      if (!reasoningState.hasStarted) {
        yield {
          type: EventType.THINKING_START,
          threadId,
          runId,
          messageId,
        };
        yield {
          type: EventType.THINKING_TEXT_MESSAGE_START,
          threadId,
          runId,
          messageId,
          role: "assistant",
        };
        reasoningState.hasStarted = true;
      }

      reasoningState.fullContent += delta.reasoning_content;
      yield {
        type: EventType.THINKING_TEXT_MESSAGE_CONTENT,
        threadId,
        runId,
        messageId,
        delta: delta.reasoning_content,
      };
    }

    // Handle tool calls
    if (delta.tool_calls) {
      for (const toolCall of delta.tool_calls) {
        const toolCallId = toolCall.id || `tool_${toolCall.index}`;

        if (toolCall.function?.name) {
          // Tool call start
          yield {
            type: EventType.TOOL_CALL_START,
            threadId,
            runId,
            toolCallId,
            toolCallName: toolCall.function.name,
          };

          // If first chunk contains arguments, emit TOOL_CALL_ARGS event
          if (toolCall.function.arguments) {
            yield {
              type: EventType.TOOL_CALL_ARGS,
              threadId,
              runId,
              toolCallId,
              delta: toolCall.function.arguments,
            };
          }

          state.toolCallsMap.set(toolCallId, {
            name: toolCall.function.name,
            args: toolCall.function.arguments || "",
          });
        } else if (toolCall.function?.arguments) {
          // Tool call arguments delta
          const existing = state.toolCallsMap.get(toolCallId);
          if (existing) {
            existing.args += toolCall.function.arguments;

            yield {
              type: EventType.TOOL_CALL_ARGS,
              threadId,
              runId,
              toolCallId,
              delta: toolCall.function.arguments,
            };
          }
        }
      }
    }
  }

  // Emit TEXT_MESSAGE_END if we had text content
  if (state.hasStarted) {
    yield {
      type: EventType.TEXT_MESSAGE_END,
      threadId,
      runId,
      messageId,
    };
  }

  if (reasoningState.hasStarted) {
    yield {
      type: EventType.THINKING_TEXT_MESSAGE_END,
      threadId,
      runId,
      messageId,
    };
    yield {
      type: EventType.THINKING_END,
      threadId,
      runId,
      messageId,
    };
  }

  // Emit TOOL_CALL_END for all tool calls
  for (const [toolCallId] of state.toolCallsMap) {
    yield {
      type: EventType.TOOL_CALL_END,
      threadId,
      runId,
      toolCallId,
    };
  }
}
