/**
 * Anthropic Converter - AGUI Protocol to Anthropic Format
 */

import Anthropic from '@anthropic-ai/sdk';
import { Message, Tool } from '@ag-ui/client';

/**
 * Convert AGUI messages to Anthropic message format
 */
export function convertMessagesToAnthropic(
  messages: Message[]
): Anthropic.MessageParam[] {
  const anthropicMessages: Anthropic.MessageParam[] = [];

  for (const msg of messages) {
    if (msg.role === 'user') {
      const contentStr = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);
      anthropicMessages.push({
        role: 'user',
        content: contentStr
      });
    } else if (msg.role === 'assistant') {
      const content: Anthropic.MessageParam['content'] = [];
      
      if (msg.content) {
        const contentStr = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);
        content.push({
          type: 'text',
          text: contentStr
        } as any);
      }

      if (msg.toolCalls) {
        for (const tc of msg.toolCalls) {
          content.push({
            type: 'tool_use',
            id: tc.id,
            name: tc.function.name,
            input: JSON.parse(tc.function.arguments)
          } as any);
        }
      }

      anthropicMessages.push({
        role: 'assistant',
        content
      });
    } else if (msg.role === 'tool') {
      const contentStr = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content);
      anthropicMessages.push({
        role: 'user',
        content: [{
          type: 'tool_result',
          tool_use_id: msg.toolCallId!,
          content: contentStr
        } as any]
      });
    }
  }

  return anthropicMessages;
}

/**
 * Convert AGUI tools to Anthropic tools format
 */
export function convertToolsToAnthropic(
  tools?: Tool[]
): Anthropic.Tool[] | undefined {
  if (!tools || tools.length === 0) {
    return undefined;
  }

  return tools.map((tool: any) => ({
    name: tool.name,
    description: tool.description,
    input_schema: typeof tool.parameters === 'string' 
      ? JSON.parse(tool.parameters) 
      : tool.parameters
  }));
}

/**
 * Create Anthropic streaming request options
 */
export function createAnthropicStreamOptions(config: {
  modelName: string;
  messages: Anthropic.MessageParam[];
  tools?: Anthropic.Tool[];
  systemPrompt?: string;
  temperature?: number;
  maxTokens?: number;
}): Anthropic.MessageCreateParamsStreaming {
  return {
    model: config.modelName,
    max_tokens: config.maxTokens || 4096,
    temperature: config.temperature,
    system: config.systemPrompt || undefined,
    messages: config.messages,
    tools: config.tools,
    stream: true
  };
}

