/**
 * LLMAgent - Direct LLM integration with AGUI protocol
 * Supports OpenAI and Anthropic models with streaming message conversion
 */

import {
  AbstractAgent,
  RunAgentInput,
  BaseEvent,
  EventType,
  Tool,
  Message,
} from "@ag-ui/client";
import { Observable } from "rxjs";

// Use type-only imports to avoid runtime dependency conflicts
// This allows users to provide their own OpenAI/Anthropic SDK instances
import type OpenAI from "openai";
import type Anthropic from "@anthropic-ai/sdk";

// Import converters
import {
  convertMessagesToOpenAI,
  convertToolsToOpenAI,
  createOpenAIStreamOptions,
} from "./converters/openai";
import {
  convertMessagesToAnthropic,
  convertToolsToAnthropic,
  createAnthropicStreamOptions,
} from "./converters/anthropic";

// Import stream processors
import { processOpenAIStream } from "./processors/openai-stream";
import { processAnthropicStream } from "./processors/anthropic-stream";
import { randomUUID } from "crypto";

// Model provider type - uses type-only imports to avoid version conflicts
export type ModelProvider = OpenAI | Anthropic;

// Model provider type detection using duck typing
type ModelProviderType = "openai" | "anthropic";

/**
 * Detect model provider type using duck typing
 * This avoids instanceof checks which require runtime imports
 */
function detectModelProviderType(model: ModelProvider): ModelProviderType {
  // OpenAI SDK has chat.completions.create
  if (
    "chat" in model &&
    typeof (model as any).chat?.completions?.create === "function"
  ) {
    return "openai";
  }
  // Anthropic SDK has messages.create
  if (
    "messages" in model &&
    typeof (model as any).messages?.create === "function"
  ) {
    return "anthropic";
  }
  throw new Error(
    "Unsupported model provider. Expected OpenAI or Anthropic SDK instance."
  );
}

export interface LLMAgentConfig {
  agentId?: string;
  name?: string;
  description?: string;
  threadId?: string;
  model: ModelProvider;
  modelName: string;
  systemPrompt?: string;
  temperature?: number;
  maxTokens?: number;
  // Function calling options
  maxToolRounds?: number; // Maximum number of tool execution rounds (default: 5)
  onToolCall?: (toolCall: {
    id: string;
    name: string;
    arguments: string;
  }) => void;
  onToolResult?: (result: {
    toolCallId: string;
    result: any;
    error?: string;
  }) => void;
}

/**
 * LLMAgent - Direct model integration with AGUI protocol
 *
 * Example:
 * ```typescript
 * import OpenAI from 'openai';
 * import { LLMAgent } from '@cloudbase/agent-adapter-llm';
 *
 * const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
 * const agent = new LLMAgent({
 *   agentId: 'my-agent',
 *   model: openai,
 *   modelName: 'gpt-4o-mini',
 *   systemPrompt: 'You are a helpful assistant.'
 * });
 * ```
 */
export class LLMAgent extends AbstractAgent {
  private model: ModelProvider;
  private modelType: ModelProviderType;
  private modelName: string;
  private systemPrompt?: string;
  private temperature?: number;
  private maxTokens?: number;
  private maxToolRounds: number;
  private onToolCall?: (toolCall: {
    id: string;
    name: string;
    arguments: string;
  }) => void;
  private onToolResult?: (result: {
    toolCallId: string;
    result: any;
    error?: string;
  }) => void;
  name: string;

  constructor(config: LLMAgentConfig) {
    super({
      agentId: config.agentId || config.name || "llm-agent",
      description: config.description || "",
      threadId: config.threadId || "",
      ...config,
    });

    this.model = config.model;
    this.modelType = detectModelProviderType(config.model);
    this.modelName = config.modelName;
    this.systemPrompt = config.systemPrompt;
    this.temperature = config.temperature;
    this.maxTokens = config.maxTokens;
    this.maxToolRounds = config.maxToolRounds || 5;
    this.onToolCall = config.onToolCall;
    this.onToolResult = config.onToolResult;
    this.name = config.name || config.agentId || "llm-agent";
  }

  run(input: RunAgentInput): Observable<BaseEvent> {
    return new Observable<BaseEvent>((subscriber) => {
      this._run(subscriber, input).catch((error) => {
        subscriber.next({
          type: EventType.RUN_ERROR,
          message: error instanceof Error ? error.message : String(error),
          code: error instanceof Error ? error.name : "UNKNOWN_ERROR",
        } as any);
        subscriber.error(error);
      });
    });
  }

  private async _run(subscriber: any, input: RunAgentInput): Promise<void> {
    const { runId, threadId, tools } = input;

    try {
      // Emit RUN_STARTED event
      subscriber.next({
        type: EventType.RUN_STARTED,
        threadId,
        runId,
      });

      // If no tools, run once
      if (!tools || tools.length === 0) {
        await this.runOnce(subscriber, input);
        subscriber.next({
          type: EventType.RUN_FINISHED,
          threadId,
          runId,
        });
        subscriber.complete();
        return;
      }

      // Auto-execute tools loop
      let messages = [...input.messages];
      let round = 0;

      while (round < this.maxToolRounds) {
        round++;

        // Collect events and tool calls from this round
        const events: BaseEvent[] = [];
        const toolCallsMap = new Map<string, { name: string; args: string }>();

        // Run model once
        await this.runOnce(subscriber, { ...input, messages }, (event) => {
          events.push(event);

          // Track tool calls
          if (event.type === EventType.TOOL_CALL_START) {
            toolCallsMap.set((event as any).toolCallId, {
              name: (event as any).toolCallName,
              args: "",
            });
          } else if (event.type === EventType.TOOL_CALL_ARGS) {
            const existing = toolCallsMap.get((event as any).toolCallId);
            if (existing) {
              existing.args += (event as any).delta;
            }
          }
        });

        // If no tool calls, we're done
        if (toolCallsMap.size === 0) {
          subscriber.next({
            type: EventType.RUN_FINISHED,
            threadId,
            runId,
          });
          subscriber.complete();
          return;
        }

        // Execute tools
        const toolCalls = Array.from(toolCallsMap.entries()).map(
          ([id, data]) => ({
            id,
            name: data.name,
            arguments: data.args,
          })
        );

        // Add assistant message with tool calls
        const assistantMessage: Message = {
          id: `msg_${Date.now()}`,
          role: "assistant",
          content: this.extractTextFromEvents(events),
          toolCalls: toolCalls.map((tc) => ({
            id: tc.id,
            type: "function" as const,
            function: {
              name: tc.name,
              arguments: tc.arguments,
            },
          })) as any,
        };
        messages.push(assistantMessage);

        // Execute tools and add results
        const toolResults = await this.executeTools(toolCalls, tools);
        const toolMessages = this.toolResultsToMessages(toolResults);
        messages.push(...toolMessages);
      }

      // Max rounds reached
      subscriber.next({
        type: EventType.RUN_ERROR,
        message: `Maximum tool execution rounds (${this.maxToolRounds}) reached`,
        code: "MAX_TOOL_ROUNDS_EXCEEDED",
      } as any);
      subscriber.complete();
    } catch (error) {
      throw error;
    }
  }

  private async runOpenAI(
    subscriber: any,
    input: RunAgentInput
  ): Promise<void> {
    const { messages, runId, threadId, tools, state, forwardedProps } = input;
    const openai = this.model as OpenAI;

    // Convert AGUI messages to OpenAI format
    const openaiMessages = convertMessagesToOpenAI(messages, this.systemPrompt);

    // Convert tools to OpenAI format
    const openaiTools = convertToolsToOpenAI(tools);

    // Create streaming completion
    const streamOptions = createOpenAIStreamOptions({
      modelName: this.modelName,
      messages: openaiMessages,
      tools: openaiTools,
      temperature: this.temperature,
      maxTokens: this.maxTokens,
      user:
        state?.__request_context__?.user?.id ||
        forwardedProps?.user ||
        randomUUID(),
    });

    const stream = await openai.chat.completions.create(streamOptions);

    // Process stream and emit AGUI events
    const messageId = `msg_${Date.now()}`;
    const context = { threadId, runId, messageId };

    for await (const event of processOpenAIStream(stream, context)) {
      subscriber.next(event);
    }
  }

  private async runAnthropic(
    subscriber: any,
    input: RunAgentInput
  ): Promise<void> {
    const { messages, runId, threadId, tools } = input;
    const anthropic = this.model as Anthropic;

    // Convert AGUI messages to Anthropic format
    const anthropicMessages = convertMessagesToAnthropic(messages);

    // Convert tools to Anthropic format
    const anthropicTools = convertToolsToAnthropic(tools);

    // Create streaming completion
    const streamOptions = createAnthropicStreamOptions({
      modelName: this.modelName,
      messages: anthropicMessages,
      tools: anthropicTools,
      systemPrompt: this.systemPrompt,
      temperature: this.temperature,
      maxTokens: this.maxTokens,
    });

    const stream = await anthropic.messages.create(streamOptions);

    // Process stream and emit AGUI events
    const messageId = `msg_${Date.now()}`;
    const context = { threadId, runId, messageId };

    for await (const event of processAnthropicStream(stream, context)) {
      subscriber.next(event);
    }
  }

  /**
   * Run model once (single round, no tool execution)
   */
  private async runOnce(
    subscriber: any,
    input: RunAgentInput,
    eventCallback?: (event: BaseEvent) => void
  ): Promise<void> {
    // Wrap subscriber to intercept events
    const wrappedSubscriber = eventCallback
      ? {
          next: (event: BaseEvent) => {
            subscriber.next(event);
            eventCallback(event);
          },
        }
      : subscriber;

    // Use pre-detected model type (duck typing) instead of instanceof
    if (this.modelType === "openai") {
      await this.runOpenAI(wrappedSubscriber, input);
    } else if (this.modelType === "anthropic") {
      await this.runAnthropic(wrappedSubscriber, input);
    } else {
      throw new Error("Unsupported model provider");
    }
  }

  /**
   * Execute tools
   */
  private async executeTools(
    toolCalls: Array<{ id: string; name: string; arguments: string }>,
    tools: Tool[]
  ): Promise<Array<{ toolCallId: string; result: any; error?: string }>> {
    const toolsMap = new Map(tools.map((t) => [t.name, t]));

    return Promise.all(
      toolCalls.map(async (toolCall) => {
        // Notify tool call
        if (this.onToolCall) {
          this.onToolCall(toolCall);
        }

        try {
          const tool = toolsMap.get(toolCall.name);
          if (!tool) {
            throw new Error(`Tool not found: ${toolCall.name}`);
          }

          // Parse arguments
          const args = JSON.parse(toolCall.arguments);

          // Execute tool
          const result = await this.executeToolFunction(tool, args);

          const toolResult = {
            toolCallId: toolCall.id,
            result,
          };

          // Notify tool result
          if (this.onToolResult) {
            this.onToolResult(toolResult);
          }

          return toolResult;
        } catch (error) {
          const toolResult = {
            toolCallId: toolCall.id,
            result: null,
            error: error instanceof Error ? error.message : String(error),
          };

          // Notify tool result
          if (this.onToolResult) {
            this.onToolResult(toolResult);
          }

          return toolResult;
        }
      })
    );
  }

  /**
   * Execute tool function
   */
  private async executeToolFunction(tool: Tool, args: any): Promise<any> {
    if ((tool as any).execute) {
      return await (tool as any).execute(args);
    }
    throw new Error(`Tool ${tool.name} does not have an execute method`);
  }

  /**
   * Convert tool results to messages
   */
  private toolResultsToMessages(
    results: Array<{ toolCallId: string; result: any; error?: string }>
  ): Message[] {
    return results.map(
      (result) =>
        ({
          id: `tool_result_${result.toolCallId}`,
          role: "tool" as const,
          toolCallId: result.toolCallId,
          content: result.error
            ? `Error: ${result.error}`
            : JSON.stringify(result.result),
        }) as any
    );
  }

  /**
   * Extract text content from events
   */
  private extractTextFromEvents(events: BaseEvent[]): string {
    let text = "";
    for (const event of events) {
      if (event.type === EventType.TEXT_MESSAGE_CONTENT) {
        text += (event as any).delta;
      }
    }
    return text;
  }
}
